content:
760          array.resize(int(qMin(chunkSize, remainingSize)));
   761
   762          while (remainingSize > 0) {
   763              const qint64 currentChunkSize = qMin(chunkSize, remainingSize);
   764              const qint64 n = inputDev->read(array.data(), currentChunkSize);
   765              Q_UNUSED(n) // except in Q_ASSERT
   766              Q_ASSERT(n == currentChunkSize);
   767              f.write(array.data(), currentChunkSize);
   768              remainingSize -= currentChunkSize;
   769          }
   770          f.setPermissions(withExecutablePerms(f.permissions(), permissions()));
   771          f.close();
   772
   773          delete inputDev;
   774          return true;
   775      }
   776      return false;
   777  }
