   820  const KArchiveEntry *KArchiveDirectory::entry(const QString &_name) const
   821  {
   822      QString name = QDir::cleanPath(_name);
   823      int pos = name.indexOf(QLatin1Char('/'));
   824      if (pos == 0) { // ouch absolute path (see also KArchive::findOrCreate)
   825          if (name.length() > 1) {
   826              name = name.mid(1);   // remove leading slash
   827              pos = name.indexOf(QLatin1Char('/'));   // look again
   828          } else { // "/"
   829              return this;
   830          }
   831      }
   832      // trailing slash ? -> remove
   833      if (pos != -1 && pos == name.length() - 1) {
   834          name = name.left(pos);
   835          pos = name.indexOf(QLatin1Char('/'));   // look again
   836      }
   837      if (pos != -1) {
   838          const QString left = name.left(pos);
   839          const QString right = name.mid(pos + 1);
   840
   841          //qCDebug(KArchiveLog) << "left=" << left << "right=" << right;
   842
   843          const KArchiveEntry *e = d->entries.value(left);
   844          if (!e || !e->isDirectory()) {
   845              return nullptr;
   846          }
   847          return static_cast<const KArchiveDirectory *>(e)->entry(right);
   848      }
   849
   850      return d->entries.value(name);
   851  }
