   462      for (;;) { // repeat until 'end of entries' signature is reached
   463          //qCDebug(KArchiveLog) << "loop starts";
   464          //qCDebug(KArchiveLog) << "dev->pos() now : " << dev->pos();
   465          int n = dev->read(buffer, 4);
   466
   467          if (n < 4) {
   468              setErrorString(tr("Invalid ZIP file. Unexpected end of file. (Error code: %1)").arg(1));
   469              return false;
   470          }
   471
   472          if (!memcmp(buffer, "PK\5\6", 4)) { // 'end of entries'
   473              //qCDebug(KArchiveLog) << "PK56 found end of archive";
   474              startOfFile = false;
   475              break;
   476          }
   477
   478          if (!memcmp(buffer, "PK\3\4", 4)) { // local file header
   479              //qCDebug(KArchiveLog) << "PK34 found local file header";
   480              startOfFile = false;
   481              // can this fail ???
   482              dev->seek(dev->pos() + 2); // skip 'version needed to extract'
