   491              int gpf = (uchar)buffer[0]; // "general purpose flag" not "general protection fault" ;-)
   492              int compression_mode = (uchar)buffer[2] | (uchar)buffer[3] << 8;
   493              uint mtime = transformFromMsDos(buffer + 4);
